// Mafium skull-octopus emblem + 1.35s underwater tentacle wing-flap animation.
// Uses full 24-bit truecolor source imagery (reading directly from the live DOM
// original image when provided) and draws the locked skull directly at native
// Retina resolution alongside forward UV-mapped tentacle ribbon meshes driven by
// anisotropic water-drag physics — preserving exact skull & sucker lighting.

export const LOGO_SWIM_DURATION_MS = 1350;
export const PHYSICS_BAKE_SEC = 1.6;
export const TENTACLE_ORDER = ['UL', 'LL', 'LR', 'UR'];

export const LOGO_PNG_DATA_URI = 'data:image/png;base64,';

const RAW_SPINES = {
  UL: [
    [0.390, 0.505], [0.325, 0.512], [0.255, 0.484], [0.190, 0.464],
    [0.130, 0.478], [0.088, 0.520], [0.078, 0.574], [0.098, 0.618],
    [0.126, 0.628],
  ],
  LL: [
    [0.455, 0.505], [0.432, 0.568], [0.382, 0.628], [0.312, 0.676],
    [0.246, 0.720], [0.196, 0.774], [0.178, 0.832], [0.196, 0.888],
    [0.248, 0.916], [0.294, 0.896], [0.296, 0.860],
  ],
  LR: [
    [0.525, 0.505], [0.542, 0.578], [0.575, 0.652], [0.628, 0.714],
    [0.698, 0.748], [0.778, 0.758], [0.855, 0.780], [0.902, 0.832],
    [0.904, 0.894], [0.860, 0.940], [0.808, 0.938],
  ],
  UR: [
    [0.622, 0.495], [0.678, 0.500], [0.738, 0.474], [0.798, 0.464],
    [0.856, 0.484], [0.886, 0.532], [0.880, 0.582], [0.848, 0.614],
    [0.812, 0.606],
  ],
};

// Slow underwater wing-flap parameters (24-ring ribbon meshes with locked cheek/jaw roots):
// each tentacle uncoils its curl gracefully upward, then sweeps smoothly back to rest.
export const TENTACLE_CONFIGS = {
  UL: {
    side: -1, phaseShift: 0.00, lockBones: 4,
    lift: 0.22, uncurl: 0.54, stiff: 0.52, damp: 0.105, dragN: 1.55, dragQ: 2.5, pullBack: 0.20,
  },
  LL: {
    side: -1, phaseShift: 0.11, lockBones: 2,
    lift: 0.21, uncurl: 0.50, stiff: 0.54, damp: 0.110, dragN: 1.70, dragQ: 2.7, pullBack: 0.42,
  },
  UR: {
    side: 1, phaseShift: 0.22, lockBones: 4,
    lift: 0.22, uncurl: 0.54, stiff: 0.52, damp: 0.105, dragN: 1.55, dragQ: 2.5, pullBack: 0.20,
  },
  LR: {
    side: 1, phaseShift: 0.30, lockBones: 2,
    lift: 0.21, uncurl: 0.52, stiff: 0.54, damp: 0.110, dragN: 1.70, dragQ: 2.7, pullBack: 0.44,
  },
};

// Pixel-verified bottom contour of the skull cheekbones & jaw so ZERO skull pixels move.
const SKULL_CUT_X = [0.00, 0.22, 0.24, 0.26, 0.28, 0.30, 0.33, 0.37, 0.41, 0.495, 0.58, 0.62, 0.66, 0.69, 0.71, 0.73, 0.76, 1.00];
const SKULL_CUT_Y = [0.00, 0.34, 0.37, 0.39, 0.418, 0.464, 0.476, 0.482, 0.496, 0.520, 0.496, 0.476, 0.472, 0.464, 0.440, 0.395, 0.35, 0.00];

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function smoothstep(e0, e1, x) {
  const t = clamp((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}

function interpPiecewise(x, xs, ys) {
  if (x <= xs[0]) return ys[0];
  const last = xs.length - 1;
  if (x >= xs[last]) return ys[last];
  for (let i = 0; i < last; i += 1) {
    if (x <= xs[i + 1]) {
      const f = (x - xs[i]) / (xs[i + 1] - xs[i]);
      return ys[i] + (ys[i + 1] - ys[i]) * f;
    }
  }
  return ys[last];
}

function buildExtendedRibbonSpine(pts, innerCount = 22) {
  const cum = [0];
  for (let i = 1; i < pts.length; i += 1) {
    cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  const total = cum[cum.length - 1] || 1;
  const poly = [];
  for (let k = 0; k < innerCount; k += 1) {
    const target = (k / (innerCount - 1)) * total;
    let seg = 0;
    while (seg < cum.length - 2 && cum[seg + 1] < target) seg += 1;
    const span = cum[seg + 1] - cum[seg] || 1;
    const f = clamp((target - cum[seg]) / span, 0, 1);
    poly.push([
      pts[seg][0] + (pts[seg + 1][0] - pts[seg][0]) * f,
      pts[seg][1] + (pts[seg + 1][1] - pts[seg][1]) * f,
    ]);
  }
  const sdx = poly[1][0] - poly[0][0];
  const sdy = poly[1][1] - poly[0][1];
  const sl = Math.hypot(sdx, sdy) || 1;
  const edx = poly[poly.length - 1][0] - poly[poly.length - 2][0];
  const edy = poly[poly.length - 1][1] - poly[poly.length - 2][1];
  const el = Math.hypot(edx, edy) || 1;
  return [
    [poly[0][0] - (sdx / sl) * 0.025, poly[0][1] - (sdy / sl) * 0.025],
    ...poly,
    [poly[poly.length - 1][0] + (edx / el) * 0.028, poly[poly.length - 1][1] + (edy / el) * 0.028],
  ];
}

export const TENTACLE_SPINES = Object.fromEntries(
  TENTACLE_ORDER.map((key) => [key, buildExtendedRibbonSpine(RAW_SPINES[key], 22)])
);

function computePolylineNormals(poly) {
  const n = poly.length;
  const nx = new Float32Array(n);
  const ny = new Float32Array(n);
  for (let i = 0; i < n; i += 1) {
    let tx;
    let ty;
    if (i === 0) {
      tx = poly[1][0] - poly[0][0];
      ty = poly[1][1] - poly[0][1];
    } else if (i === n - 1) {
      tx = poly[n - 1][0] - poly[n - 2][0];
      ty = poly[n - 1][1] - poly[n - 2][1];
    } else {
      const dx1 = poly[i][0] - poly[i - 1][0];
      const dy1 = poly[i][1] - poly[i - 1][1];
      const l1 = Math.hypot(dx1, dy1) || 1;
      const dx2 = poly[i + 1][0] - poly[i][0];
      const dy2 = poly[i + 1][1] - poly[i][1];
      const l2 = Math.hypot(dx2, dy2) || 1;
      tx = dx1 / l1 + dx2 / l2;
      ty = dy1 / l1 + dy2 / l2;
    }
    const len = Math.hypot(tx, ty) || 1;
    nx[i] = -ty / len;
    ny[i] = tx / len;
  }
  return { nx, ny };
}

/**
 * Whole-body pose stays in place by default; optional subtle underwater buoyancy
 * recoil surges gently up-left on the downstroke and floats back on recovery.
 */
export function computeLogoSwimPose(progress, { recoil = false } = {}) {
  const t = clamp(progress, 0, 1);
  if (!recoil) return { dx: 0, dy: 0, rot: 0, scale: 1, opacity: 1 };
  const w = 2 * Math.PI * t;
  const surge = -Math.sin(w - 1.15) * 0.5 + 0.5;
  const dx = -0.045 * (surge - 0.5);
  const dy = -0.055 * (surge - 0.5);
  const rot = -0.025 * Math.sin(w - 0.8);
  return { dx, dy, rot, scale: 1, opacity: 1 };
}

const PHYSICS_SAMPLES = 120;

function simulateWaterTentacle(rest, cfg, { periodic }) {
  const m = rest.length - 1;
  const L = new Float64Array(m);
  const theta0 = new Float64Array(m);
  for (let i = 0; i < m; i += 1) {
    const dx = rest[i + 1][0] - rest[i][0];
    const dy = rest[i + 1][1] - rest[i][1];
    L[i] = Math.hypot(dx, dy);
    theta0[i] = Math.atan2(dy, dx);
  }

  const thUnwrapped = new Float64Array(m);
  thUnwrapped[0] = theta0[0];
  for (let i = 1; i < m; i += 1) {
    let diff = theta0[i] - theta0[i - 1];
    while (diff > Math.PI) diff -= 2 * Math.PI;
    while (diff < -Math.PI) diff += 2 * Math.PI;
    thUnwrapped[i] = thUnwrapped[i - 1] + diff;
  }
  const restTurn = new Float64Array(m);
  for (let i = 1; i < m; i += 1) restTurn[i] = thUnwrapped[i] - thUnwrapped[i - 1];

  const dirSign = -cfg.side;
  const scaleM = m / 11;
  const K = new Float64Array(m);
  const D = new Float64Array(m);
  const width = new Float64Array(m);
  const I = new Float64Array(m);
  const qOpen = new Float64Array(m);

  for (let i = 0; i < m; i += 1) {
    const s = (i + 0.5) / m;
    K[i] = (cfg.stiff * scaleM) * ((1 - 0.70 * s) ** 1.3);
    D[i] = (cfg.damp * scaleM) * ((1 - 0.56 * s) ** 1.1);
    width[i] = 1 - 0.62 * s;
  }
  for (let j = 0; j < m; j += 1) {
    let arm = 0;
    let inert = 0.00018;
    for (let i = j; i < m; i += 1) {
      arm += L[i];
      inert += (L[i] * width[i] * 0.7) * (arm * arm) * 0.5;
    }
    I[j] = inert;
    if (j >= cfg.lockBones && j < m - 1) {
      const u = (j - cfg.lockBones) / Math.max(1, m - 2 - cfg.lockBones);
      const shoulderLift = dirSign * (cfg.lift / scaleM) * Math.exp(-(((u - 0.14) / 0.36) ** 2));
      const inwardCurl = Math.max(0, -restTurn[j] * dirSign);
      const uncurl = dirSign * cfg.uncurl * inwardCurl * (0.35 + 0.65 * u);
      qOpen[j] = shoulderLift + uncurl;
    }
  }

  const q = new Float64Array(m);
  const dq = new Float64Array(m);
  const px = new Float64Array(m + 1);
  const py = new Float64Array(m + 1);
  const mx = new Float64Array(m);
  const my = new Float64Array(m);
  const prevMx = new Float64Array(m);
  const prevMy = new Float64Array(m);
  const th = new Float64Array(m);
  const Fx = new Float64Array(m);
  const Fy = new Float64Array(m);

  const fk = () => {
    px[0] = rest[0][0];
    py[0] = rest[0][1];
    let acc = 0;
    for (let i = 0; i < m; i += 1) {
      acc += q[i];
      const a = theta0[i] + acc;
      th[i] = a;
      px[i + 1] = px[i] + L[i] * Math.cos(a);
      py[i + 1] = py[i] + L[i] * Math.sin(a);
      mx[i] = 0.5 * (px[i] + px[i + 1]);
      my[i] = 0.5 * (py[i] + py[i + 1]);
    }
  };

  fk();
  prevMx.set(mx);
  prevMy.set(my);

  const substeps = 4;
  const stepsPerCycle = PHYSICS_SAMPLES * substeps;
  const dt = PHYSICS_BAKE_SEC / stepsPerCycle;
  const warmupSteps = periodic ? stepsPerCycle * 4 : 0;
  const totalSteps = warmupSteps + stepsPerCycle;

  const framesQ = [];
  for (let step = 0; step < totalSteps; step += 1) {
    let flapAct = 0;
    if (periodic) {
      const ph = ((step % stepsPerCycle) / stepsPerCycle + cfg.phaseShift) % 1;
      const w = 2 * Math.PI * ph;
      flapAct = clamp(0.44 - 0.54 * Math.cos(w) + 0.14 * Math.sin(w) - 0.08 * Math.sin(2 * w), -0.18, 1.08);
    } else {
      const t = step / stepsPerCycle;
      // Staggered active wing-flap inside [0..0.72] leaving smooth underwater coasting
      // [0.70..1.00] so every tentacle decelerates naturally to 0 angle & 0 velocity.
      const t0 = cfg.phaseShift * 0.22;
      const t1 = t0 + 0.65;
      if (t > t0 && t < t1) {
        const u = (t - t0) / (t1 - t0);
        const lift = Math.pow(Math.sin(Math.PI * clamp(u / 0.66, 0, 1)), 1.6);
        const pullBack = u > 0.44
          ? Math.sin(Math.PI * clamp((u - 0.44) / 0.56, 0, 1))
          : 0;
        flapAct = 1.15 * lift - (cfg.pullBack ?? 0.30) * pullBack;
      }
    }

    fk();
    for (let i = 0; i < m; i += 1) {
      const vx = (mx[i] - prevMx[i]) / dt;
      const vy = (my[i] - prevMy[i]) / dt;
      prevMx[i] = mx[i];
      prevMy[i] = my[i];
      const tx = Math.cos(th[i]);
      const ty = Math.sin(th[i]);
      const nx = -ty;
      const ny = tx;
      const vn = vx * nx + vy * ny;
      const vt = vx * tx + vy * ty;
      const area = L[i] * width[i];
      const fn = -(cfg.dragN + cfg.dragQ * Math.abs(vn)) * vn * area;
      const ft = -(cfg.dragN * 0.07) * vt * area;
      Fx[i] = fn * nx + ft * tx;
      Fy[i] = fn * ny + ft * ty;
    }

    for (let j = cfg.lockBones; j < m - 1; j += 1) {
      let tw = 0;
      const pxj = px[j];
      const pyj = py[j];
      for (let i = j; i < m; i += 1) {
        tw += (mx[i] - pxj) * Fy[i] - (my[i] - pyj) * Fx[i];
      }
      const targetQ = qOpen[j] * flapAct;
      const accel = (K[j] * (targetQ - q[j]) + tw) / I[j];
      // Semi-implicit damping keeps even low-inertia distal tip joints unconditionally smooth
      dq[j] = clamp((dq[j] + accel * dt) / (1 + (D[j] / I[j]) * dt), -10, 10);
      q[j] = clamp(q[j] + dq[j] * dt, -0.35, 0.35);
    }

    if (step >= warmupSteps && (step - warmupSteps) % substeps === 0) {
      framesQ.push(new Float32Array(q));
    }
  }

  const nFrames = framesQ.length;
  if (periodic) {
    const startQ = framesQ[0];
    const endQ = new Float32Array(q);
    for (let f = 0; f < nFrames; f += 1) {
      const blend = f / nFrames;
      const row = framesQ[f];
      for (let j = 0; j < m; j += 1) {
        row[j] += (startQ[j] - endQ[j]) * blend;
      }
    }
  } else {
    // Feather any tiny residual gently over the final 20% with C2 quintic ease
    for (let f = 0; f < nFrames; f += 1) {
      const t = f / (nFrames - 1);
      if (t > 0.80) {
        const s = (t - 0.80) / 0.20;
        const fade = 1 - s * s * s * (s * (s * 6 - 15) + 10);
        const row = framesQ[f];
        for (let j = 0; j < m; j += 1) row[j] *= fade;
      }
    }
    framesQ[0].fill(0);
    framesQ[nFrames - 1].fill(0);
  }

  return { L, theta0, framesQ };
}

const PERIODIC_CACHE = new Map();
const ONESHOT_CACHE = new Map();
const RIG_CACHE = new Map();

function getPhysicsTrack(key, periodic) {
  const cache = periodic ? PERIODIC_CACHE : ONESHOT_CACHE;
  if (!cache.has(key)) {
    cache.set(key, simulateWaterTentacle(TENTACLE_SPINES[key], TENTACLE_CONFIGS[key], { periodic }));
  }
  return cache.get(key);
}

/**
 * Computes arc-length-preserving bent spine points and segment angles for tentacle `key`
 * from the slender-body underwater fluid-drag simulation.
 */
export function computeTentacleBones(key, progress, { periodic = false } = {}) {
  const rest = TENTACLE_SPINES[key];
  const m = rest.length - 1;
  const track = getPhysicsTrack(key, periodic);
  const { L, theta0, framesQ } = track;
  const n = framesQ.length;

  const t = periodic ? (((progress % 1) + 1) % 1) : clamp(progress, 0, 1);
  const pos = periodic ? t * n : t * (n - 1);
  const i0 = Math.floor(pos) % n;
  const i1 = periodic ? (i0 + 1) % n : Math.min(n - 1, i0 + 1);
  const frac = pos - Math.floor(pos);

  const q0 = framesQ[i0];
  const q1 = framesQ[i1];
  const points = new Array(rest.length);
  points[0] = [rest[0][0], rest[0][1]];
  const phis = new Float32Array(m);

  let cumAngle = 0;
  for (let i = 0; i < m; i += 1) {
    cumAngle += q0[i] + (q1[i] - q0[i]) * frac;
    phis[i] = cumAngle;
    const a = theta0[i] + cumAngle;
    points[i + 1] = [
      points[i][0] + L[i] * Math.cos(a),
      points[i][1] + L[i] * Math.sin(a),
    ];
  }

  return { points, phis };
}

function closestDistSqToSpine(px, py, poly) {
  let best = 1e9;
  for (let i = 0; i < poly.length - 1; i += 1) {
    const ax = poly[i][0];
    const ay = poly[i][1];
    const dx = poly[i + 1][0] - ax;
    const dy = poly[i + 1][1] - ay;
    const len2 = dx * dx + dy * dy + 1e-12;
    const proj = clamp(((px - ax) * dx + (py - ay) * dy) / len2, 0, 1);
    const rx = px - (ax + proj * dx);
    const ry = py - (ay + proj * dy);
    const d2 = rx * rx + ry * ry;
    if (d2 < best) best = d2;
  }
  return best;
}

/**
 * Keys out ONLY the exterior, eye sockets, and nostrils matching `keyBg` (e.g. #0b0a0d)
 * via flood-fill, leaving every interior skull and sucker pixel 100% unmodified truecolor.
 */
function keyBackgroundInPlace(rgba, size, keyBg) {
  let [br, bg, bb] = keyBg;
  // Adapt to actual decoded corner pixel when dark (handles AVIF/WebP/Display-P3 ±3 shifts on phones)
  if (rgba[3] > 240 && Math.max(rgba[0], rgba[1], rgba[2]) < 40) {
    br = rgba[0]; bg = rgba[1]; bb = rgba[2];
  }
  const total = size * size;
  const dist = new Float32Array(total);
  const isBgSeed = new Uint8Array(total);
  for (let i = 0; i < total; i += 1) {
    const o = i * 4;
    const dr = rgba[o] - br;
    const dg = rgba[o + 1] - bg;
    const db = rgba[o + 2] - bb;
    const d = Math.sqrt(dr * dr + dg * dg + db * db);
    dist[i] = d;
    if (d < 16) isBgSeed[i] = 1;
  }

  const transparent = new Uint8Array(total);
  const queue = new Int32Array(total);
  let qHead = 0;
  let qTail = 0;
  const push = (idx) => {
    if (!transparent[idx] && isBgSeed[idx]) {
      transparent[idx] = 1;
      queue[qTail] = idx;
      qTail += 1;
    }
  };

  for (let x = 0; x < size; x += 1) {
    push(x);
    push((size - 1) * size + x);
  }
  for (let y = 0; y < size; y += 1) {
    push(y * size);
    push(y * size + (size - 1));
  }
  // Seed the 2 eye sockets and 2 nostrils (normalized coordinates in 416x416 emblem frame)
  for (const [nx, ny] of [[0.385, 0.375], [0.615, 0.375], [0.481, 0.462], [0.519, 0.462]]) {
    const sx = clamp(Math.round(nx * size), 0, size - 1);
    const sy = clamp(Math.round(ny * size), 0, size - 1);
    push(sy * size + sx);
  }

  while (qHead < qTail) {
    const idx = queue[qHead];
    qHead += 1;
    const x = idx % size;
    const y = (idx - x) / size;
    if (x > 0) push(idx - 1);
    if (x < size - 1) push(idx + 1);
    if (y > 0) push(idx - size);
    if (y < size - 1) push(idx + size);
  }

  // Dilate transparent mask by 3px for crisp anti-aliased fringe un-premultiplication
  let fringe = transparent.slice();
  for (let pass = 0; pass < 3; pass += 1) {
    const next = fringe.slice();
    for (let y = 0; y < size; y += 1) {
      const row = y * size;
      for (let x = 0; x < size; x += 1) {
        const i = row + x;
        if (!fringe[i]) continue;
        if (x > 0) next[i - 1] = 1;
        if (x < size - 1) next[i + 1] = 1;
        if (y > 0) next[i - size] = 1;
        if (y < size - 1) next[i + size] = 1;
      }
    }
    fringe = next;
  }

  for (let i = 0; i < total; i += 1) {
    if (!fringe[i]) continue;
    const o = i * 4;
    const d = dist[i];
    if (transparent[i] && d < 4) {
      rgba[o] = 0; rgba[o + 1] = 0; rgba[o + 2] = 0; rgba[o + 3] = 0;
      continue;
    }
    const alpha = clamp((d - 5) / 20, 0, 1);
    if (alpha <= 0.005) {
      rgba[o] = 0; rgba[o + 1] = 0; rgba[o + 2] = 0; rgba[o + 3] = 0;
      continue;
    }
    const aSafe = Math.max(alpha, 0.06);
    rgba[o] = clamp(Math.round(br + (rgba[o] - br) / aSafe), 0, 255);
    rgba[o + 1] = clamp(Math.round(bg + (rgba[o + 1] - bg) / aSafe), 0, 255);
    rgba[o + 2] = clamp(Math.round(bb + (rgba[o + 2] - bb) / aSafe), 0, 255);
    rgba[o + 3] = Math.round(alpha * 255);
  }
}

function getSegmentedRig(img, texSize, { sourceCrop = null, keyBg = null, cacheKey = 'default' } = {}) {
  const srcKey = img.currentSrc || (typeof img.src === 'string' && !img.src.startsWith('data:') ? img.src : '');
  const fullKey = `${cacheKey}:${texSize}:${srcKey}`;
  if (RIG_CACHE.has(fullKey)) return RIG_CACHE.get(fullKey);

  const work = document.createElement('canvas');
  work.width = texSize;
  work.height = texSize;
  let wctx = null;
  try { wctx = work.getContext('2d', { willReadFrequently: true }); } catch { wctx = null; }
  if (!wctx) return null;
  wctx.imageSmoothingEnabled = true;
  if ('imageSmoothingQuality' in wctx) wctx.imageSmoothingQuality = 'high';
  wctx.clearRect(0, 0, texSize, texSize);
  if (sourceCrop) {
    // Use 5-arg drawImage(img, dx, dy, dw, dh) rather than 9-arg source-rect cropping:
    // on 2x/3x Retina phones, <picture>/<img srcset="... 2x"> reports density-corrected
    // img.naturalWidth (e.g. 240 for a 480px bitmap), while 9-arg drawImage indexes raw
    // bitmap pixels (480px), cropping only the top-left quarter. 5-arg drawImage always
    // maps the full decoded bitmap cleanly across every browser and DPR.
    const drawW = texSize / sourceCrop.w;
    const drawH = texSize / sourceCrop.h;
    wctx.drawImage(img, -sourceCrop.x * drawW, -sourceCrop.y * drawH, drawW, drawH);
  } else {
    wctx.drawImage(img, 0, 0, texSize, texSize);
  }
  let src;
  try {
    src = wctx.getImageData(0, 0, texSize, texSize).data;
  } catch {
    return null;
  }
  if (keyBg) {
    keyBackgroundInPlace(src, texSize, keyBg);
  }

  const headCanvas = document.createElement('canvas');
  headCanvas.width = texSize;
  headCanvas.height = texSize;
  let hctx = null;
  try { hctx = headCanvas.getContext('2d'); } catch { hctx = null; }
  if (!hctx) return null;
  const headImg = hctx.createImageData(texSize, texSize);
  const headData = headImg.data;

  const tentacleTex = TENTACLE_ORDER.map(() => new Uint8ClampedArray(texSize * texSize * 4));
  const spines = TENTACLE_ORDER.map((k) => TENTACLE_SPINES[k]);
  const restNormals = spines.map((poly) => computePolylineNormals(poly));
  const rPosList = spines.map((poly) => new Float32Array(poly.length).fill(0.022));
  const rNegList = spines.map((poly) => new Float32Array(poly.length).fill(0.022));

  for (let y = 0; y < texSize; y += 1) {
    const py = (y + 0.5) / texSize;
    for (let x = 0; x < texSize; x += 1) {
      const idx4 = (y * texSize + x) * 4;
      const a = src[idx4 + 3];
      if (a === 0) continue;

      const px = (x + 0.5) / texSize;
      const yCut = interpPiecewise(px, SKULL_CUT_X, SKULL_CUT_Y);
      const isCenterBridge = px > 0.39 && px < 0.60;
      const headW = (1 - smoothstep(yCut - (isCenterBridge ? 0.012 : 0.004), yCut + (isCenterBridge ? 0.020 : 0.006), py))
        * smoothstep(0.18, 0.21, px)
        * (1 - smoothstep(0.79, 0.82, px));

      const r = src[idx4];
      const g = src[idx4 + 1];
      const b = src[idx4 + 2];

      if (headW > 0.002) {
        headData[idx4] = r;
        headData[idx4 + 1] = g;
        headData[idx4 + 2] = b;
        headData[idx4 + 3] = Math.round(a * headW);
      }

      // Full overlap under the locked skull seam guarantees alpha === 1.0 with zero dark seam line
      // while lockBones keeps all underlying cheek/jaw attachment segments 100% motionless.
      const underHead = 1 - smoothstep(0.68, 0.94, headW);
      if (underHead <= 0.002) continue;

      const d0 = Math.sqrt(closestDistSqToSpine(px, py, spines[0])) + ((px > 0.388 || py > (px > 0.165 ? 0.622 : 0.655)) ? 1 : 0);
      const d1 = Math.sqrt(closestDistSqToSpine(px, py, spines[1])) + (px > 0.496 ? 1 : 0);
      const d2 = Math.sqrt(closestDistSqToSpine(px, py, spines[2])) + ((px < 0.490 || (px > 0.61 && py < 0.545)) ? 1 : 0);
      const d3 = Math.sqrt(closestDistSqToSpine(px, py, spines[3])) + ((px < 0.595 || py > 0.640) ? 1 : 0);

      let owner = 0;
      let best = d0;
      if (d1 < best) { best = d1; owner = 1; }
      if (d2 < best) { best = d2; owner = 2; }
      if (d3 < best) { owner = 3; }

      const outA = Math.round(a * underHead);
      const dst = tentacleTex[owner];
      dst[idx4] = r;
      dst[idx4 + 1] = g;
      dst[idx4 + 2] = b;
      dst[idx4 + 3] = outA;

      if (outA > 10) {
        const poly = spines[owner];
        const nRings = poly.length;
        let bestRing = 0;
        let bestRD2 = 1e9;
        for (let ri = 0; ri < nRings; ri += 1) {
          const rx = px - poly[ri][0];
          const ry = py - poly[ri][1];
          const rd2 = rx * rx + ry * ry;
          if (rd2 < bestRD2) { bestRD2 = rd2; bestRing = ri; }
        }
        if (bestRD2 < 0.125 * 0.125) {
          const norms = restNormals[owner];
          const rPos = rPosList[owner];
          const rNeg = rNegList[owner];
          const rLo = Math.max(0, bestRing - 1);
          const rHi = Math.min(nRings - 1, bestRing + 1);
          for (let ri = rLo; ri <= rHi; ri += 1) {
            const rx = px - poly[ri][0];
            const ry = py - poly[ri][1];
            if (rx * rx + ry * ry >= 0.125 * 0.125) continue;
            const sn = rx * norms.nx[ri] + ry * norms.ny[ri];
            if (sn > 0) {
              const need = sn + 0.012;
              if (need > rPos[ri]) rPos[ri] = need;
            } else {
              const need = -sn + 0.012;
              if (need > rNeg[ri]) rNeg[ri] = need;
            }
          }
        }
      }
    }
  }

  const restRibbons = spines.map((poly, ti) => {
    const n = poly.length;
    const rPos = rPosList[ti];
    const rNeg = rNegList[ti];
    const norms = restNormals[ti];
    // Cap ONLY against true geometric fold-over (curvR * 0.94) on tight curls so outer S-bend
    // shoulders and glossy rim highlights are NEVER notched or clipped.
    for (let i = 1; i < n - 1; i += 1) {
      const v1x = poly[i][0] - poly[i - 1][0];
      const v1y = poly[i][1] - poly[i - 1][1];
      const v2x = poly[i + 1][0] - poly[i][0];
      const v2y = poly[i + 1][1] - poly[i][1];
      const l1 = Math.hypot(v1x, v1y);
      const l2 = Math.hypot(v2x, v2y);
      const turn = Math.atan2(v1x * v2y - v1y * v2x, v1x * v2x + v1y * v2y);
      if (Math.abs(turn) > 0.05) {
        const curvR = (0.5 * (l1 + l2)) / Math.abs(turn);
        const cap = Math.max(0.024, curvR * 0.94);
        if (turn > 0) rPos[i] = Math.min(rPos[i], cap);
        else rNeg[i] = Math.min(rNeg[i], cap);
      }
    }
    // Keep tip cap tidy without clipping mid-arm suckers
    for (let i = n - 2; i < n; i += 1) {
      rPos[i] = Math.min(rPos[i], rPos[i - 1] * 1.04);
      rNeg[i] = Math.min(rNeg[i], rNeg[i - 1] * 1.04);
    }

    const uNeg = new Float32Array(n); const vNeg = new Float32Array(n);
    const uMid = new Float32Array(n); const vMid = new Float32Array(n);
    const uPos = new Float32Array(n); const vPos = new Float32Array(n);
    for (let i = 0; i < n; i += 1) {
      const cx = poly[i][0];
      const cy = poly[i][1];
      uMid[i] = cx; vMid[i] = cy;
      uNeg[i] = cx - norms.nx[i] * rNeg[i]; vNeg[i] = cy - norms.ny[i] * rNeg[i];
      uPos[i] = cx + norms.nx[i] * rPos[i]; vPos[i] = cy + norms.ny[i] * rPos[i];
    }
    return { rPos, rNeg, uNeg, vNeg, uMid, vMid, uPos, vPos };
  });

  hctx.putImageData(headImg, 0, 0);
  const rig = { texSize, headCanvas, tentacleTex, restRibbons };
  RIG_CACHE.set(fullKey, rig);
  return rig;
}

function createTentacleRenderer(rig, spriteSize) {
  const pad = 0.20;
  const span = 1 + 2 * pad;
  const { texSize, tentacleTex, restRibbons } = rig;

  const spriteCanvas = document.createElement('canvas');
  spriteCanvas.width = spriteSize;
  spriteCanvas.height = spriteSize;
  let sctx = null;
  try { sctx = spriteCanvas.getContext('2d'); } catch { sctx = null; }
  if (!sctx) return null;

  const totalPx = spriteSize * spriteSize;
  const imgData = sctx.createImageData(spriteSize, spriteSize);
  const outBytes = imgData.data;
  const outU32 = new Uint32Array(outBytes.buffer, outBytes.byteOffset, totalPx);
  const accR = new Float32Array(totalPx);
  const accG = new Float32Array(totalPx);
  const accB = new Float32Array(totalPx);
  const accA = new Float32Array(totalPx);
  const stamp = new Uint8Array(totalPx);
  const pxScale = spriteSize / span;
  const inv255 = 1 / 255;
  const texMax = texSize - 1;
  const texStride = texSize * 4;

  let dirtyMinX = spriteSize;
  let dirtyMaxX = -1;
  let dirtyMinY = spriteSize;
  let dirtyMaxY = -1;
  let prevMinX = 0;
  let prevMaxX = spriteSize - 1;
  let prevMinY = 0;
  let prevMaxY = spriteSize - 1;

  function rasterizeTri(
    tex, stampId,
    ax, ay, au, av,
    bx, by, bu, bv,
    cx, cy, cu, cv,
  ) {
    let x0 = ax; let y0 = ay; let u0 = au; let v0 = av;
    let x1 = bx; let y1 = by; let u1 = bu; let v1 = bv;
    let x2 = cx; let y2 = cy; let u2 = cu; let v2 = cv;
    let area = (x1 - x0) * (y2 - y0) - (y1 - y0) * (x2 - x0);
    if (area > -1e-5 && area < 1e-5) return;
    if (area < 0) {
      let tmp = x1; x1 = x2; x2 = tmp;
      tmp = y1; y1 = y2; y2 = tmp;
      tmp = u1; u1 = u2; u2 = tmp;
      tmp = v1; v1 = v2; v2 = tmp;
      area = -area;
    }
    const minX = Math.max(0, Math.floor(x0 < x1 ? (x0 < x2 ? x0 : x2) : (x1 < x2 ? x1 : x2)));
    const maxX = Math.min(spriteSize - 1, Math.ceil(x0 > x1 ? (x0 > x2 ? x0 : x2) : (x1 > x2 ? x1 : x2)));
    const minY = Math.max(0, Math.floor(y0 < y1 ? (y0 < y2 ? y0 : y2) : (y1 < y2 ? y1 : y2)));
    const maxY = Math.min(spriteSize - 1, Math.ceil(y0 > y1 ? (y0 > y2 ? y0 : y2) : (y1 > y2 ? y1 : y2)));
    if (maxX < minX || maxY < minY) return;
    if (minX < dirtyMinX) dirtyMinX = minX;
    if (maxX > dirtyMaxX) dirtyMaxX = maxX;
    if (minY < dirtyMinY) dirtyMinY = minY;
    if (maxY > dirtyMaxY) dirtyMaxY = maxY;

    const invArea = 1 / area;
    const dw0x = (y1 - y2) * invArea;
    const dw0y = (x2 - x1) * invArea;
    const dw1x = (y2 - y0) * invArea;
    const dw1y = (x0 - x2) * invArea;
    const cx0 = minX + 0.5;
    const cy0 = minY + 0.5;
    let rowW0 = ((x1 - cx0) * (y2 - cy0) - (y1 - cy0) * (x2 - cx0)) * invArea;
    let rowW1 = ((x2 - cx0) * (y0 - cy0) - (y2 - cy0) * (x0 - cx0)) * invArea;

    const tu0 = u0 * texSize - 0.5;
    const tv0 = v0 * texSize - 0.5;
    const du1 = (u1 - u0) * texSize;
    const dv1 = (v1 - v0) * texSize;
    const du2 = (u2 - u0) * texSize;
    const dv2 = (v2 - v0) * texSize;
    // Slight negative barycentric margin eliminates 1px floating-point cracks along shared
    // ribbon triangle seams at 4x zoom while stamp[] guarantees single-paint per tentacle.
    const eps = -2e-3;

    for (let py = minY; py <= maxY; py += 1) {
      let w0 = rowW0;
      let w1 = rowW1;
      const rowOff = py * spriteSize;
      for (let px = minX; px <= maxX; px += 1) {
        if (w0 >= eps && w1 >= eps) {
          const w2 = 1 - w0 - w1;
          if (w2 >= eps) {
            const pIdx = rowOff + px;
            if (stamp[pIdx] !== stampId) {
              const fx = tu0 + w1 * du1 + w2 * du2;
              const fy = tv0 + w1 * dv1 + w2 * dv2;
              const ix = fx | 0;
              const iy = fy | 0;
              if (fx >= 0 && ix < texMax && fy >= 0 && iy < texMax) {
                const tx = fx - ix;
                const ty = fy - iy;
                const omx = 1 - tx;
                const omy = 1 - ty;
                const i00 = (iy * texSize + ix) * 4;
                const i10 = i00 + 4;
                const i01 = i00 + texStride;
                const i11 = i01 + 4;

                // Premultiplied alpha-weighted bilinear filter prevents transparent (0,0,0) edge
                // texels from darkening bright specular sucker rims and outer tentacle highlights.
                const k00 = omx * omy * tex[i00 + 3];
                const k10 = tx * omy * tex[i10 + 3];
                const k01 = omx * ty * tex[i01 + 3];
                const k11 = tx * ty * tex[i11 + 3];
                const aSum = k00 + k10 + k01 + k11;
                if (aSum > 1.0) {
                  stamp[pIdx] = stampId;
                  const a = aSum * inv255;
                  const invA = 1 - a;
                  accR[pIdx] = (tex[i00] * k00 + tex[i10] * k10 + tex[i01] * k01 + tex[i11] * k11) * inv255 + accR[pIdx] * invA;
                  accG[pIdx] = (tex[i00 + 1] * k00 + tex[i10 + 1] * k10 + tex[i01 + 1] * k01 + tex[i11 + 1] * k11) * inv255 + accG[pIdx] * invA;
                  accB[pIdx] = (tex[i00 + 2] * k00 + tex[i10 + 2] * k10 + tex[i01 + 2] * k01 + tex[i11 + 2] * k11) * inv255 + accB[pIdx] * invA;
                  accA[pIdx] = a + accA[pIdx] * invA;
                }
              }
            }
          }
        }
        w0 += dw0x;
        w1 += dw1x;
      }
      rowW0 += dw0y;
      rowW1 += dw1y;
    }
  }

  let frameStamp = 0;

  function renderTentacles(progress, { periodic = false } = {}) {
    for (let y = prevMinY; y <= prevMaxY; y += 1) {
      const off = y * spriteSize;
      accR.fill(0, off + prevMinX, off + prevMaxX + 1);
      accG.fill(0, off + prevMinX, off + prevMaxX + 1);
      accB.fill(0, off + prevMinX, off + prevMaxX + 1);
      accA.fill(0, off + prevMinX, off + prevMaxX + 1);
      outU32.fill(0, off + prevMinX, off + prevMaxX + 1);
    }
    dirtyMinX = spriteSize;
    dirtyMaxX = -1;
    dirtyMinY = spriteSize;
    dirtyMaxY = -1;

    for (let ti = 0; ti < TENTACLE_ORDER.length; ti += 1) {
      frameStamp = (frameStamp % 250) + 1;
      if (frameStamp === 1) stamp.fill(0);

      const key = TENTACLE_ORDER[ti];
      const tex = tentacleTex[ti];
      const rib = restRibbons[ti];
      const { points } = computeTentacleBones(key, progress, { periodic });
      const n = points.length;
      const norms = computePolylineNormals(points);

      const xNeg = new Float32Array(n); const yNeg = new Float32Array(n);
      const xMid = new Float32Array(n); const yMid = new Float32Array(n);
      const xPos = new Float32Array(n); const yPos = new Float32Array(n);

      for (let i = 0; i < n; i += 1) {
        const cx = points[i][0];
        const cy = points[i][1];
        xMid[i] = (cx + pad) * pxScale;
        yMid[i] = (cy + pad) * pxScale;
        xNeg[i] = (cx - norms.nx[i] * rib.rNeg[i] + pad) * pxScale;
        yNeg[i] = (cy - norms.ny[i] * rib.rNeg[i] + pad) * pxScale;
        xPos[i] = (cx + norms.nx[i] * rib.rPos[i] + pad) * pxScale;
        yPos[i] = (cy + norms.ny[i] * rib.rPos[i] + pad) * pxScale;
      }

      const { uNeg, vNeg, uMid, vMid, uPos, vPos } = rib;
      for (let i = 0; i < n - 1; i += 1) {
        const j = i + 1;
        rasterizeTri(
          tex, frameStamp,
          xNeg[i], yNeg[i], uNeg[i], vNeg[i],
          xMid[i], yMid[i], uMid[i], vMid[i],
          xMid[j], yMid[j], uMid[j], vMid[j],
        );
        rasterizeTri(
          tex, frameStamp,
          xNeg[i], yNeg[i], uNeg[i], vNeg[i],
          xMid[j], yMid[j], uMid[j], vMid[j],
          xNeg[j], yNeg[j], uNeg[j], vNeg[j],
        );
        rasterizeTri(
          tex, frameStamp,
          xMid[i], yMid[i], uMid[i], vMid[i],
          xPos[i], yPos[i], uPos[i], vPos[i],
          xPos[j], yPos[j], uPos[j], vPos[j],
        );
        rasterizeTri(
          tex, frameStamp,
          xMid[i], yMid[i], uMid[i], vMid[i],
          xPos[j], yPos[j], uPos[j], vPos[j],
          xMid[j], yMid[j], uMid[j], vMid[j],
        );
      }
    }

    if (dirtyMaxX >= dirtyMinX) {
      for (let y = dirtyMinY; y <= dirtyMaxY; y += 1) {
        const row = y * spriteSize;
        for (let x = dirtyMinX; x <= dirtyMaxX; x += 1) {
          const i = row + x;
          const a = accA[i];
          if (a > 0.002) {
            const o = i * 4;
            const inv = 1 / a;
            outBytes[o] = Math.min(255, (accR[i] * inv + 0.5) | 0);
            outBytes[o + 1] = Math.min(255, (accG[i] * inv + 0.5) | 0);
            outBytes[o + 2] = Math.min(255, (accB[i] * inv + 0.5) | 0);
            outBytes[o + 3] = Math.min(255, (a * 255 + 0.5) | 0);
          }
        }
      }
      prevMinX = dirtyMinX;
      prevMaxX = dirtyMaxX;
      prevMinY = dirtyMinY;
      prevMaxY = dirtyMaxY;
    } else {
      prevMinX = 0; prevMaxX = -1; prevMinY = 0; prevMaxY = -1;
    }

    sctx.putImageData(imgData, 0, 0);
    return spriteCanvas;
  }

  return { renderTentacles, span };
}

/**
 * Plays the 1.35s underwater tentacle wing-flap animation on page load and replays
 * cleanly on click. Draws the locked skull directly onto the display canvas at full
 * native Retina resolution so skull and sucker lighting match the original reference
 * image with zero start/end brightness pop.
 */
export function startLogoSwimIntro({
  container,
  trigger = container,
  sourceImg = null,
  sourceCrop = null,
  keyBg = null,
  fillBg = null,
  cacheKey = 'default',
  durationMs = LOGO_SWIM_DURATION_MS,
  loop = false,
  recoil = false,
  contentScale = 1,
  clipToBox = false,
  playOnClick = true,
  autoStart = true,
  canvasClass = 'mark-swim',
  createImage = () => new window.Image(),
} = {}) {
  let destroyed = false;
  let running = false;
  let playCount = 0;
  let rafId = 0;
  let stageCanvas = null;
  let loadedImg = null;
  let usingFallbackImg = false;
  let pendingPlay = false;
  let visListener = null;
  let pagehideListener = null;
  let clickListener = null;

  const stopRun = () => {
    running = false;
    if (rafId) {
      cancelAnimationFrame(rafId);
      rafId = 0;
    }
    if (stageCanvas) {
      stageCanvas.remove();
      stageCanvas = null;
    }
    if (container) {
      delete container.dataset.swimming;
    }
  };

  const destroy = () => {
    if (destroyed) return;
    destroyed = true;
    stopRun();
    if (visListener) {
      document.removeEventListener('visibilitychange', visListener);
      visListener = null;
    }
    if (pagehideListener) {
      window.removeEventListener('pagehide', pagehideListener);
      pagehideListener = null;
    }
    if (clickListener && trigger) {
      trigger.removeEventListener('click', clickListener);
      clickListener = null;
    }
  };

  const isReducedMotion = () => Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches);

  if (!container || typeof document === 'undefined' || typeof window === 'undefined') {
    return { destroy, replay: () => {}, isRunning: () => false, playCount: () => 0 };
  }

  const ua = (typeof window !== 'undefined' ? window.navigator?.userAgent : '') || (typeof navigator !== 'undefined' ? navigator.userAgent : '');
  if (/jsdom/i.test(ua || '') || typeof requestAnimationFrame !== 'function') {
    return { destroy, replay: () => {}, isRunning: () => false, playCount: () => 0 };
  }

  const startCycle = (img) => {
    if (destroyed || !img || isReducedMotion()) return;
    stopRun();

    const rect = container.getBoundingClientRect?.();
    const boxSize = Math.max(
      20,
      Math.round((clipToBox ? container.clientWidth : rect?.width) || container.clientWidth || rect?.width || 34),
    );
    const emblemSize = boxSize * contentScale;
    const rawDpr = window.devicePixelRatio || 1;
    const vvScale = window.visualViewport?.scale || 1;
    const dpr = Math.min(Math.max(rawDpr * vvScale, rawDpr), 4);
    const texSize = Math.min(416, Math.max(128, Math.round(emblemSize * dpr)));
    const spriteSize = Math.min(584, Math.max(160, Math.round(texSize * 1.40)));

    const rigOpts = usingFallbackImg
      ? { sourceCrop: null, keyBg: null, cacheKey: `${cacheKey}:fb` }
      : { sourceCrop, keyBg, cacheKey };
    const rig = getSegmentedRig(img, texSize, rigOpts);
    const creature = rig ? createTentacleRenderer(rig, spriteSize) : null;
    if (!creature) return;

    const pad = clipToBox ? 0 : 0.24;
    const offset = clipToBox ? 0 : Math.round(pad * boxSize);
    const cssSize = boxSize + offset * 2;
    const restCenter = offset + boxSize * 0.5;

    stageCanvas = document.createElement('canvas');
    stageCanvas.className = canvasClass;
    stageCanvas.setAttribute('aria-hidden', 'true');
    if (clipToBox) {
      stageCanvas.style.inset = '0';
      stageCanvas.style.width = '100%';
      stageCanvas.style.height = '100%';
    } else {
      stageCanvas.style.left = `${-offset}px`;
      stageCanvas.style.top = `${-offset}px`;
      stageCanvas.style.width = `${cssSize}px`;
      stageCanvas.style.height = `${cssSize}px`;
    }
    stageCanvas.width = Math.max(1, Math.round(cssSize * dpr));
    stageCanvas.height = Math.max(1, Math.round(cssSize * dpr));

    let ctx = null;
    try { ctx = stageCanvas.getContext('2d'); } catch { ctx = null; }
    if (!ctx) {
      stopRun();
      return;
    }
    ctx.imageSmoothingEnabled = true;
    if ('imageSmoothingQuality' in ctx) ctx.imageSmoothingQuality = 'high';

    running = true;
    playCount += 1;
    container.dataset.swimming = '';
    container.append(stageCanvas);

    let startTime = null;
    const drawTentacleSize = emblemSize * creature.span;
    const halfEmblem = emblemSize / 2;

    const step = (now) => {
      rafId = 0;
      if (destroyed || !running) return;
      if (startTime === null) startTime = now;
      const elapsed = Math.max(0, now - startTime);
      const progress = durationMs > 0
        ? (loop ? (elapsed % durationMs) / durationMs : Math.min(1, elapsed / durationMs))
        : 1;

      if (!loop && progress >= 1) {
        stopRun();
        return;
      }

      const pose = computeLogoSwimPose(progress, { recoil });
      const tentacleSprite = creature.renderTentacles(progress, { periodic: loop });

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      if (fillBg) {
        ctx.fillStyle = fillBg;
        ctx.fillRect(0, 0, cssSize, cssSize);
      } else {
        ctx.clearRect(0, 0, cssSize, cssSize);
      }
      ctx.save();
      ctx.globalAlpha = pose.opacity;
      ctx.translate(restCenter + pose.dx * emblemSize, restCenter + pose.dy * emblemSize);
      ctx.rotate(pose.rot);
      ctx.scale(pose.scale, pose.scale);
      // 1. Animated tentacles (forward UV ribbon meshes)
      ctx.drawImage(tentacleSprite, -drawTentacleSize / 2, -drawTentacleSize / 2, drawTentacleSize, drawTentacleSize);
      // 2. Locked skull drawn directly at full native Retina resolution (zero double-resample blur!)
      ctx.drawImage(rig.headCanvas, -halfEmblem, -halfEmblem, emblemSize, emblemSize);
      ctx.restore();

      rafId = requestAnimationFrame(step);
    };

    rafId = requestAnimationFrame(step);
  };

  const replay = () => {
    if (destroyed || isReducedMotion()) return;
    if (loadedImg) {
      startCycle(loadedImg);
    } else {
      pendingPlay = true;
    }
  };

  const onImageReady = (img) => {
    if (destroyed) return;
    loadedImg = img;
    if (!pendingPlay) return;
    pendingPlay = false;
    if (document.visibilityState === 'hidden') {
      if (!visListener) {
        visListener = () => {
          if (document.visibilityState !== 'hidden') {
            document.removeEventListener('visibilitychange', visListener);
            visListener = null;
            startCycle(loadedImg);
          }
        };
        document.addEventListener('visibilitychange', visListener);
      }
    } else {
      startCycle(loadedImg);
    }
  };

  if (playOnClick && trigger) {
    clickListener = () => replay();
    trigger.addEventListener('click', clickListener);
  }

  pagehideListener = () => stopRun();
  window.addEventListener('pagehide', pagehideListener);

  if (autoStart && !isReducedMotion()) {
    pendingPlay = true;
  }

  const loadFallback = () => {
    if (destroyed || loadedImg) return;
    usingFallbackImg = true;
    const fb = createImage();
    fb.decoding = 'sync';
    fb.onload = () => onImageReady(fb);
    fb.onerror = () => stopRun();
    fb.src = LOGO_PNG_DATA_URI;
    if (fb.complete && fb.naturalWidth > 0) {
      onImageReady(fb);
    }
  };

  if (sourceImg) {
    if (sourceImg.complete && sourceImg.naturalWidth > 0) {
      onImageReady(sourceImg);
    } else {
      sourceImg.addEventListener?.('load', () => onImageReady(sourceImg), { once: true });
      sourceImg.addEventListener?.('error', () => loadFallback(), { once: true });
    }
  } else {
    loadFallback();
  }

  return {
    destroy,
    replay,
    isRunning: () => running,
    playCount: () => playCount,
  };
}
